function Delete(n){const t=Swal.mixin({customClass:{confirmButton:"btn btn-success",cancelButton:"btn btn-danger"},buttonsStyling:!1});t.fire({title:"Are you sure?",text:"You won't be able to recover this!",icon:"warning",showCancelButton:!0,confirmButtonText:"Yes, delete it!",cancelButtonText:"No, cancel!",reverseButtons:!0}).then(i=>{i.isConfirmed?$.ajax({type:"DELETE",url:n,success:function(n){$.unblockUI();n.success?(swal.fire("Deleted!",n.message,"success"),dataTable.ajax.reload()):Swal.fire({icon:"error",title:"Oops...",text:n.message,footer:"Feed back message"})},beforeSend:function(){blockcallback()},error:function(){$.unblockUI();Swal.fire({icon:"error",title:"Oops...",text:"Something went wrong!",footer:"Check internet connectivity!"})},complete:function(){$.unblockUI()}}):i.dismiss===Swal.DismissReason.cancel&&t.fire("Cancelled","Action aborted!","error")})}function blockcallback(){$.blockUI({message:'<div class="bs-spinner mt-4 mt-lg-0"><div class= "spinner-border text-success mr-2 mt-2" style="width: 10rem; height: 10rem;" role="status"><span class="sr-only">Loading...<\/span><\/div> ',fadeIn:800,overlayCSS:{backgroundColor:"#1b2024",opacity:.8,zIndex:1200,cursor:"wait"},css:{border:0,color:"#fff",zIndex:1201,padding:0,backgroundColor:"transparent"},onBlock:function(){}})}$(document).ready(function(){dataTable=$("#tablenews").DataTable({processing:!0,serverSide:!0,filter:!0,ajax:{url:"/Home/GetFeedBack",type:"POST",datatype:"json"},columnDefs:[{targets:[0],visible:!0,searchable:!0}],columns:[{data:"id",render:function(n,t,i,r){return r.row+r.settings._iDisplayStart+1}},{data:"name",autoWidth:!0},{data:"email",autoWidth:!0},{data:"subject",render:function(n){return n.length>30?n.substring(0,30)+".....":n}},{data:"message",render:function(n){return n.length>50?n.substring(0,50)+".....":n}},{data:"createdDate",autoWidth:!0,render:function(n){var t=new Date(n).getHours();let i=t>=12?"pm":"am";return n.toLocaleString("YYYY-MM-dd").slice(0,19).replace("T"," ")+" "+i}},{data:"isRead",autoWidth:!0,className:"text-center",render:function(n){return n==!0?`<label class="bg-warning badge"><i class="fa fa-envelope-open" aria-hidden="true"></i></label>`:`<label class="bg-success badge"><i class="fa fa-envelope" aria-hidden="true"></i></label>`}},{data:"id",render:function(n){return`
                        <div class="d-flex justify-content-between">
                            <a class="btn btn-success btn-sm" title="View feed back from customer" href="/Messaging/Feed-Back/Message-Detail?id=${n}" style="cursor:pointer">
                                <i class="bi bi-eye"></i>
                            </a>
                            <a onclick=Delete("/api/DeleteFeedback/${n}") class="btn btn-danger btn-sm pl-2" href="#" style="cursor:pointer">
                                <i class="bi bi-trash3"></i>
                            </a>
                        </div>
                    `}}]})});